// Turning a place NAME from prose into a coordinate — tier 1 of the cascade (#47).
//
// The public Nominatim is not used here at all, and that is a decision rather than an
// oversight. A recurring batch job falls into its restricted bucket at 4 requests a
// minute, bulk geocoding is explicitly discouraged, and the current policy singles out
// code generated by no-code/low-code/LLM tooling. This pipeline is all three. The
// cascade is Wikidata → local GeoNames → a paid geocoder, and this module is the first
// rung: free, CC0, and results may be stored without attribution obligations.
//
// The harder problem is not fetching but CHOOSING. "Cambridge" is a city in England, a
// city in Massachusetts, and a dozen other places; "Victoria" is a state, a station, a
// queen and a film. A label match alone silently writes the wrong coordinate, which is
// worse than writing none — so every candidate must prove it is a geographic thing and
// must survive a same-name rival before it is accepted.

import { haversineKm } from "./geo.mjs";
import { finiteOrNull } from "./numbers.mjs";
import { normalizePlaceName } from "./place-dedup.mjs";
import { WIKIDATA_SPARQL } from "./user-agent.mjs";

export { WIKIDATA_SPARQL };

// Measured, not guessed. A 40-name batch returns HTTP 504: the label|altLabel union
// across the whole geographic class tree is expensive per name, and WDQS hard-fails a
// query at 60 seconds. Eight is comfortable.
//
// The two failures mean OPPOSITE things and must not be handled alike:
//   * 504 — the query was too heavy. Shrink the batch; waiting longer changes nothing.
//   * 429 — we were too fast. Wait; a smaller batch changes nothing.
// Seen live, a 504 was immediately followed by a 429, so the gap is generous too.
export const MAX_NAMES_PER_QUERY = 8;
export const QUERY_GAP_MS = 5000;

// What to do about a failed query, by status. Returning a decision rather than a
// boolean keeps the caller from inventing its own interpretation.
export function retryPlan(status) {
  // 502 belongs with 504 rather than with the permanent failures: WDQS answers a query
  // that overran its budget with either, depending on which layer gave up first. Seen
  // live in one run — a batch of eight returned 504 and the next returned 502.
  if (status === 504 || status === 502 || status === 500) {
    return { action: "shrink_batch", waitMs: QUERY_GAP_MS };
  }
  if (status === 429 || status === 503) return { action: "back_off", waitMs: QUERY_GAP_MS * 4 };
  return { action: "give_up", waitMs: 0 };
}

// How many times a batch may be halved before we accept that the names themselves are
// the problem. Eight names becomes one in three halvings.
export const MAX_SHRINK_DEPTH = 3;

// How many times we wait out a rate limit. Counted SEPARATELY from splitting: they
// answer different problems, and sharing one budget let a single 429 consume the room
// needed to shrink a query that was simply too heavy.
export const MAX_BACKOFF_ATTEMPTS = 3;

// Wikidata is CC0: no attribution owed, no share-alike, results freely storable. That
// is precisely why it is the first rung.
export const WIKIDATA_LICENSE = Object.freeze({ name: "CC0", url: "https://creativecommons.org/publicdomain/zero/1.0/" });

// This used to filter candidates with `wdt:P31/wdt:P279* wd:Q618123` — descent from
// "geographical feature". It was correct and it did not work: measured live, the query
// took 65 SECONDS and returned HTTP 504 for a SINGLE name, while a trivial query to the
// same service answered in 0.45s. An unbounded subclass closure, evaluated for every
// label match, is simply too expensive; moving it into FILTER EXISTS changed nothing
// because the planner reorders it back.
//
// Dropping the closure takes the same query to under three seconds. Two things replace
// it, and neither is the ontology:
//
//   1. REQUIRING A COORDINATE does most of the work already. Checked live: "Skyfall"
//      returns nothing at all, because the film has no P625. The closure was redundant
//      for exactly the case its comment cited.
//   2. It was not redundant for everything — "Victoria" also matches a shipwreck and a
//      bark, which do carry coordinates. So the direct P31 type comes back with each
//      row and obvious non-places are dropped below, in code.
//
// This is a heuristic backstop, not a taxonomy, and it is allowed to be: every result
// lands in the review queue with its Wikidata id, where "Victoria (shipwreck)" is
// obvious to a human in a way it never is to a regex.
const NON_PLACE_TYPES = new Set([
  "shipwreck", "ship", "sailing ship", "bark", "barque", "brig", "schooner", "steamship",
  "submarine", "aircraft", "spacecraft", "locomotive", "yacht", "ferry", "vessel",
]);

export function isPlaceType(typeLabel) {
  const label = String(typeLabel ?? "").trim().toLowerCase();
  if (!label) return true; // an untyped entity with a coordinate is still a place
  return !NON_PLACE_TYPES.has(label);
}

// **A state is not a point.** Measured over the 246 coordinates of the first real run:
// six rows are a "U.S. state" and one a "province of Canada" — New Jersey at 40.0,-74.5,
// Minnesota at 46.0,-94.0, British Columbia in the middle of its own forest. Those are
// centroids of an administrative polygon, and standing on one tells a reader nothing.
//
// The owner's rule of 04.08 already said it for islands: *an island named as a location
// goes on the map as an AREA, never as a point.* A state is the same shape of claim and a
// larger error. The name is kept and the coordinate declined, which is what the schema
// expects of a place we cannot locate.
//
// Cities, towns, county seats and census-designated places are NOT this. A city centroid is
// where a reader would aim, and 27 of the 246 are exactly that. The test is anchored so
// that "state capital" and "city in the state of New York" — both city types — do not read
// as states.
const AREA_TYPE_PATTERNS = [
  /^u\.?s\.? state$/i,
  /^state of the united states/i,
  /^(federal |constituent |autonomous )?state$/i,
  /^state of \w+/i,
  /^province(\b| of )/i,
  /^(autonomous )?region(\b| of )/i,
  /^territory(\b| of )/i,
  /^(sovereign )?country$/i,
  /^oblast|^krai$|^prefecture(\b| of )/i,
  /^autonomous community/i,
  /^constituent country/i,
];

export function isAreaNotAPoint(place) {
  const labels = [...(place?.types ?? []), place?.type_label].filter(Boolean);
  return labels.some((label) => AREA_TYPE_PATTERNS.some((pattern) => pattern.test(String(label).trim())));
}

// A name too generic to disambiguate. These match hundreds of entities, and a
// population tiebreak between them is a coin toss dressed up as a decision.
const TOO_GENERIC = new Set([
  "city centre", "downtown", "the studio", "a studio", "the set", "on location",
  "various locations", "the city", "the street", "unknown",
]);

// The name a gazetteer can actually answer.
//
// Models return the place as the PROSE names it, which is right for display and wrong
// for lookup: the first live run asked Wikidata about "the Old Royal Naval College in
// Greenwich", "Hankley Common in Surrey" and "the Golden Dragon casino in Macau", and
// got nothing — while "Hankley Common" on its own resolves immediately. The enclosing
// area is already carried separately in `area_hint`, so it is duplication rather than
// information here.
//
// Only the leading article and a trailing "in <area>" are removed. A comma clause is
// left alone: "Cambridge, Massachusetts" IS the gazetteer name, and stripping it would
// turn an answerable name into an ambiguous one.
export function gazetteerName(name) {
  return String(name ?? "")
    .trim()
    .replace(/^(the|a|an)\s+/i, "")
    .replace(/\s+in\s+[^,]+$/i, "")
    .trim();
}

export function isGeocodableName(name) {
  const normalized = normalizePlaceName(name);
  if (!normalized || normalized.length < 3) return false;
  if (TOO_GENERIC.has(normalized)) return false;
  // A bare number or a year is not a place.
  return !/^\d+$/.test(normalized);
}

// Escape for a SPARQL string literal. Prose contains quotes and backslashes, and an
// unescaped one does not merely fail — it changes the query.
export function sparqlLiteral(value) {
  return String(value ?? "")
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"')
    .replace(/[\n\r\t]/g, " ");
}

// One query for many names. Matches the label OR an alias, requires the thing to be a
// geographic feature, and requires a coordinate — an entity we cannot place is not an
// answer. Population comes back for the tiebreak, and `hint` narrows by the enclosing
// area when the prose gave one.
// **A French article names French places in French, and the gazetteer speaks every
// language.** Measured on the first real run: `observatoire Griffith`, `manoir Playboy`,
// `Colombie-Britannique` and `Sony Pictures Studios de Culver City` all came back
// `no_candidate` — asked in English, they are nothing. Asked with the tag of the edition
// they came from, Wikidata answers **Griffith Observatory** and **British Columbia**.
//
// Nothing is translated. The name is the one the source used, asked in the language the
// source is written in, which is the only honest way to look it up — a model asked to
// render it in English would be inventing a name the article never carried.
//
// `languages` maps the name to the edition it came from. A name with no entry is asked in
// English, as before.
export function buildGeocodeQuery(names, { languages = null } = {}) {
  const wanted = (Array.isArray(names) ? names : [])
    .filter(isGeocodableName)
    .slice(0, MAX_NAMES_PER_QUERY);
  if (wanted.length === 0) return null;

  const values = wanted.flatMap((name) => {
    const literal = `"${sparqlLiteral(name)}"`;
    const language = languages?.get?.(name);
    // Both tags, not one: an English name in a French article still answers in English,
    // and asking only in French would lose it.
    return language && language !== "en" ? [`${literal}@en`, `${literal}@${language}`] : [`${literal}@en`];
  }).join(" ");

  return `SELECT ?name ?place ?placeLabel ?lat ?lng ?population ?typeLabel ?exact ?countryLabel ?ancLabel WHERE {
  VALUES ?name { ${values} }
  ?place rdfs:label|skos:altLabel ?name .
  # Whether the name is the entity's OWN label or merely one of its aliases. "Istanbul
  # Grill" matches "Istanbul" by alias; the city matches by label. That difference is
  # evidence, and it is what stops a pub outranking a city.
  BIND(EXISTS { ?place rdfs:label ?name } AS ?exact)
  ?place p:P625/psv:P625 ?node .
  ?node wikibase:geoLatitude ?lat ; wikibase:geoLongitude ?lng .
  OPTIONAL { ?place wdt:P1082 ?population }
  OPTIONAL { ?place wdt:P31 ?type }
  # The country the candidate is actually in. Not used to CHOOSE one — see
  # contradictsArea — only to refuse one the prose says is somewhere else.
  OPTIONAL { ?place wdt:P17 ?country }
  # The whole administrative chain, not just the immediate parent. Measured: the immediate
  # P131 of Wildwood Regional Park is Ventura County, so a hint of "California" matches
  # nothing and a correct place is refused. Transitive, it matches.
  OPTIONAL { ?place wdt:P131*|wdt:P17 ?anc }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}`;
}

// Group the flat SPARQL rows by the name that was asked for.
export function groupByName(bindings) {
  const grouped = new Map();
  for (const row of Array.isArray(bindings) ? bindings : []) {
    const name = row?.name?.value;
    const lat = finiteOrNull(row?.lat?.value);
    const lng = finiteOrNull(row?.lng?.value);
    const qid = String(row?.place?.value ?? "").split("/").pop();
    if (!name || lat === null || lng === null || !/^Q[1-9]\d*$/.test(qid)) continue;

    // A shipwreck has a coordinate and is not a place you can visit as a location.
    const typeLabel = row?.typeLabel?.value ?? null;
    if (!isPlaceType(typeLabel)) continue;

    const key = normalizePlaceName(name);
    if (!grouped.has(key)) grouped.set(key, []);
    // One entity comes back once per P31 value; the same id is one candidate.
    const already = grouped.get(key).find((candidate) => candidate.wikidata_id === qid);
    if (already) {
      // One entity comes back once per (P31 x ancestor) pair; the extra rows carry the rest
      // of its chain and nothing else.
      if (row?.ancLabel?.value) already.chain.add(row.ancLabel.value);
      if (row?.countryLabel?.value) {
        already.countries.add(row.countryLabel.value);
        already.chain.add(row.countryLabel.value);
      }
      if (typeLabel) already.types.add(typeLabel);
      continue;
    }
    grouped.get(key).push({
      wikidata_id: qid,
      name: row?.placeLabel?.value ?? name,
      lat,
      lng,
      population: finiteOrNull(row?.population?.value),
      type_label: typeLabel,
      exact_label: row?.exact?.value === "true",
      country: row?.countryLabel?.value ?? null,
      chain: new Set([row?.ancLabel?.value, row?.countryLabel?.value].filter(Boolean)),
      // Every P17, because a place can have more than one. Jerusalem's are Israel and
      // Palestine, and `country` holds whichever row arrived first: on 07.11.2026 that was
      // Palestine, so a hint of "Israel" refused the city itself and left a village in
      // Thuringia as the "ambiguous" answer. Tiberias and the Dead Sea went the same way.
      countries: new Set([row?.countryLabel?.value].filter(Boolean)),
      // Every P31, not only the first row's. An entity comes back once per type and the
      // one that arrives first is arbitrary — Honolulu is a "county seat" on one row and a
      // "consolidated city-county" on another, and a rule reading only one of them is a
      // coin toss.
      types: new Set([typeLabel].filter(Boolean)),
    });
  }
  return grouped;
}

// How far apart two candidates must be before they count as rival places rather than
// two records of the same one. Well under a city, well over a rounding difference.
export const RIVAL_DISTANCE_KM = 25;

// How near the hint a candidate must be for the hint to have said anything about it.
//
// Without this the hint was actively harmful. Checked live: with London as the hint,
// "Istanbul" resolved to Istanbul Grill, a pub in Manchester, because Manchester is
// closer to London than Turkey is; "Shanghai" resolved to a neighbourhood in Italy.
// The hint exists to separate Cambridge England from Cambridge Massachusetts — two
// comparable candidates, one of them where the user is looking. Ranking the whole world
// by distance from a city is a different operation that happens to use the same
// arithmetic, and it produces a confident wrong answer every time.
export const HINT_RADIUS_KM = 100;

// When a population difference stops being a coin toss and becomes evidence.
//
// This module refuses to rank Cambridge England (145,000) against Cambridge
// Massachusetts (118,000), and that refusal is right: at 1.2x, picking the bigger one
// invents an answer. But refusing EVERY population comparison cost real recall —
// checked live, "Shanghai" and "Adana" were both refused, and their rivals are
// unincorporated communities and a subbarrio with no recorded population at all
// against cities of 24.8 million and 1.77 million.
//
// The first version of this used a RATIO — fifty to one — and it was wrong. Checked
// against real data, "Victoria" has 110 exact-label candidates, and the state of
// Australia (7,074,468) beats a Canadian district (110,942) by 63x. That clears any
// sane ratio while being a hopeless choice among 110 real places. A ratio measures the
// gap between two known quantities; it cannot tell a city beside a hamlet from a state
// beside a city.
//
// What separates the two cases is whether there is anything to compare with at all.
// Wikidata records a population for every settlement of consequence, so a rival with
// none is not a contender — and when EVERY rival is silent, this is not a judgement
// call, it is the absence of one. A single rival with a recorded population is enough
// to refuse, which is why Cambridge, Glencoe and Victoria all still come back unplaced.
//
// The winner must also be large in absolute terms, because a missing population is
// missing data rather than a measured zero.
export const NOTABLE_POPULATION = 100_000;

export function dominantByPopulation(list) {
  const ranked = [...list].sort((a, b) => (b.population ?? 0) - (a.population ?? 0));
  const [top, ...rivals] = ranked;
  if (!top?.population || top.population < NOTABLE_POPULATION) return null;
  return rivals.every((candidate) => candidate.population == null) ? top : null;
}

function kmApart(a, b) {
  const dLat = (a.lat - b.lat) * 111.32;
  const dLng = (a.lng - b.lng) * 111.32 * Math.cos((a.lat * Math.PI) / 180);
  return Math.hypot(dLat, dLng);
}

// Pick one candidate, or refuse.
//
// The refusal is the important half. Two genuinely different places sharing a name —
// Cambridge England and Cambridge Massachusetts — must NOT be resolved by taking the
// bigger one: the prose said "Cambridge" and we do not know which, so writing either
// coordinate is inventing an answer. A `near` hint from the same prose is the only
// thing that may break such a tie.
// The candidate list travels WITH the decision, refusal or not (#149).
//
// A refusal used to throw the candidates away, and that is right for the question this
// function answers — "which one of these is the place" — but it discards the answer to a
// different question somebody else has to ask: "is this coordinate anywhere near a place
// of that name at all". `london`, `paris` and `los angeles` all refuse here as ambiguous
// homonyms, and every one of them is a perfectly good thing to sanity-check against.
//
// Returned rather than made public through a second, looser policy. Two definitions of
// "which candidate wins" is how the two surfaces start disagreeing; one definition plus
// the evidence it worked from is not.
// **The country a written hint names, or nothing.**
//
// This exists because of Bognor. The prose said Joyce wrote in Bognor and `area_hint` said
// England; the gazetteer returned **Bognor, Ontario** and the row was stored with a Canadian
// coordinate. Nothing caught it, because it was not a tie — plain "Bognor" has one
// candidate, and the English town is called Bognor Regis. No tie-break could ever have
// helped; only a contradiction can.
//
// **And a hint may only refuse, never select.** `near` is documented as "the only thing
// allowed to break a homonym tie, and it comes from the request rather than from a model",
// and that rule is right: `area_hint` is written by a model, and letting it pick between
// candidates would let an invented area move a pin. Refusing is the safe half of the same
// information — a coordinate we decline to store costs a name without a point, which the
// schema already expects.
//
// Silence is the default. An unrecognised hint says nothing, and so does a candidate with
// no country.
const COUNTRY_BY_AREA_WORD = Object.freeze({
  england: "United Kingdom", scotland: "United Kingdom", wales: "United Kingdom",
  "northern ireland": "United Kingdom", britain: "United Kingdom",
  "great britain": "United Kingdom", uk: "United Kingdom", "united kingdom": "United Kingdom",
  usa: "United States", us: "United States", america: "United States",
  "united states": "United States", "united states of america": "United States",
});

// Names that are a country AND something else, so they say nothing on their own. Georgia is
// a country and a US state; a hint of "Savannah, Georgia" must not be read as the Caucasus.
const AMBIGUOUS_AREA_WORDS = new Set(["georgia", "ireland", "macedonia", "luxembourg", "singapore"]);

export function areaNamesCountry(area, knownCountries = []) {
  const text = String(area ?? "").trim().toLowerCase();
  if (!text) return null;
  const parts = text.split(",").map((part) => part.trim()).filter(Boolean);
  for (const part of [...parts].reverse()) {
    if (AMBIGUOUS_AREA_WORDS.has(part)) return null;
    if (COUNTRY_BY_AREA_WORD[part]) return COUNTRY_BY_AREA_WORD[part];
    // A country the gazetteer itself named for one of the candidates. Matching against
    // what came back rather than against a list we maintain keeps the two in step.
    const match = knownCountries.find((country) => String(country).toLowerCase() === part);
    if (match) return match;
  }
  return null;
}

const normalizeAreaWord = (value) => String(value ?? "")
  .toLowerCase().replace(/[^a-z0-9 ]/g, " ").replace(/\s+/g, " ").trim();

// A hint that cannot contradict anything, because it is not the name of an administrative
// unit. Two kinds, and both are common in what a model writes into `area_hint`:
//
//   a description        "city where principal photography took place", "Location of the house"
//   an informal region   "French Alps", "Cape Ann area", "Central European city", "Asia"
//
// Neither appears in a P131 chain however right it is, so reading either as a contradiction
// refuses correct coordinates. Measured over 246 placed rows, these two guards together
// took the false refusals from 19 to 2.
const HINT_IS_PROSE = /\b(where|which|used|filmed|filming|shot|scenes?|location of|took place|is |was |were |house|home of)\b/i;
const HINT_IS_INFORMAL = /\b(asia|europe|africa|america|north|south|east|west|central|region|area|metropolitan|alps|coast|bay|near|outskirts|greater)\b/i;

export function hintNamesAnAdministrativeArea(area) {
  const text = String(area ?? "").trim();
  return Boolean(text) && text.length <= 42 && !HINT_IS_PROSE.test(text) && !HINT_IS_INFORMAL.test(text);
}

// Is this candidate's own chain detailed enough to disagree with a hint about a city?
//
// Many entities carry no P131 at all — studios, parks, railways — so their chain is the
// country and themselves. Such a chain cannot contradict "Culver City, California"; it
// simply does not know. Refusing on it cost seven correct coordinates in the measurement.
function chainIsInformative(place) {
  const own = normalizeAreaWord(place?.name);
  const ancestors = [...(place?.chain ?? [])].map(normalizeAreaWord).filter((word) => word && word !== own);
  return ancestors.length >= 2 ? ancestors : null;
}

export function contradictsArea(place, area, knownCountries = []) {
  // The country test first: it works even on a thin chain, and it is the one that caught
  // Bognor.
  const claimed = areaNamesCountry(area, knownCountries);
  const countries = [...(place?.countries ?? []), place?.country].filter(Boolean).map((c) => String(c).toLowerCase());
  if (claimed && countries.length && !countries.includes(claimed.toLowerCase())) {
    return true;
  }

  // The chain is labelled in English. A hint written in another script — "ירושלים, ישראל"
  // from a Hebrew article — shares no letters with it, so every word would "disagree" and
  // every candidate would be refused. Such a hint cannot judge, and says nothing.
  if (!/\p{Script=Latin}/u.test(String(area ?? ""))) return false;

  // Then the chain, which is what a city-level hint needs. New-York resolved to Niu-York in
  // Ukraine on a hint of "New York"; no country is named there, so nothing above could see
  // it, and the chain says Toretsk Hromada / Bakhmut Raion / Ukraine.
  const ancestors = chainIsInformative(place);
  if (!ancestors || !hintNamesAnAdministrativeArea(area)) return false;

  const words = new Set([normalizeAreaWord(place?.name), ...ancestors]
    .flatMap((word) => [word, COUNTRY_BY_AREA_WORD[word] && normalizeAreaWord(COUNTRY_BY_AREA_WORD[word])])
    .filter(Boolean));
  const tokens = String(area).split(",").map(normalizeAreaWord).filter((token) => token.length > 2)
    .flatMap((token) => [token, COUNTRY_BY_AREA_WORD[token] && normalizeAreaWord(COUNTRY_BY_AREA_WORD[token])])
    .filter(Boolean);
  if (tokens.length === 0) return false;

  // ANY token agreeing is agreement. A hint names a place and its enclosing areas, and
  // matching the widest of them is still the hint and the candidate talking about the same
  // part of the world.
  return !tokens.some((token) => [...words].some((word) => word === token || word.includes(token) || token.includes(word)));
}

// **When the chain says nothing about the town the hint names, measure instead.**
//
// "Clifton Village", hint "Bristol, England", resolved to Clifton in Nottingham: the chain
// holds England and so does the hint, so `contradictsArea` finds them agreeing on the widest
// word. Requiring the hint's MOST SPECIFIC word to appear in the chain was tried, and it
// refused Wildwood Regional Park and 126 correct rows like it — Wildwood's P131 is Ventura
// County, so "Thousand Oaks" is simply absent. A name match cannot tell a chain that is
// SILENT about a town from one that names a DIFFERENT one.
//
// Distance can. Measured on 21.09 over the 48 placed Wikipedia rows whose hint town is
// missing from their chain: a model writes the nearest big name it knows, so a right
// coordinate sits close to it — Pinewood in Iver is 29 km from "London", Phillips Academy in
// Andover 30 km from "Cambridge", Warner Hollywood 10 km from "Burbank". Every row under
// 80 km was a correct coordinate with a loose hint. Above 150 km sat Clifton (188), Saint
// Francisville placed in Illinois for "Louisiana" (309) and Milton Academy placed in
// Wisconsin for "Cambridge, Massachusetts" (704) — three wrong pins — and one right one,
// Alamo Village in Brackettville, whose hint says Greenville (579): the price, paid once.
//
// Three guards keep it honest. The town is looked for only where the chain is silent. A
// town that is itself an AREA — "British Columbia", a state — has no point to measure from,
// so it cannot refuse anything. And a town is taken only if it agrees with the REST of the
// hint, because American town names repeat: a Cambridge sits in Wisconsin too, a few miles
// from the wrong Milton Academy, and would have excused it.
export const FAR_FROM_HINT_KM = 150;

export function hintTownTheChainDoesNotName(place, area) {
  if (!place || !hintNamesAnAdministrativeArea(area)) return null;
  const parts = String(area).split(",").map((part) => part.trim()).filter(Boolean);
  if (parts.length < 2) return null;
  const town = parts[0];
  const key = normalizeAreaWord(town);
  if (key.length <= 2) return null;
  const words = [place.name, ...(place.chain ?? [])].map(normalizeAreaWord).filter((word) => word.length > 2);
  if (words.some((word) => word === key || word.includes(key) || key.includes(word))) return null;
  return town;
}

export function isFarFromHintTown(place, townCandidates, area, farKm = FAR_FROM_HINT_KM) {
  const lat = finiteOrNull(place?.lat);
  const lng = finiteOrNull(place?.lng);
  if (lat === null || lng === null) return false;
  const rest = String(area ?? "").split(",").slice(1).join(",").trim();
  // AGREES, not merely "does not contradict". A town whose own chain is too thin to disagree
  // with anything cannot vouch for anything either: measured, "Windsor, Buckinghamshire"
  // (a wrong hint — Windsor is in Berkshire) excluded the right Windsor for contradicting
  // Buckinghamshire, and a far Windsor with a one-line chain slipped in and refused Leavesden.
  const usable = (Array.isArray(townCandidates) ? townCandidates : []).filter((town) =>
    finiteOrNull(town?.lat) !== null && finiteOrNull(town?.lng) !== null
    && !isAreaNotAPoint(town)
    && chainIsInformative(town) !== null
    && (!rest || !contradictsArea(town, rest)));
  // No town to measure from is no evidence, and the silence stays what it was.
  if (usable.length === 0) return false;
  // geo.mjs takes [lat, lng] pairs. Handed objects it returns NaN, and NaN > farKm is false —
  // a check that could never refuse anything, and would have looked like one that passed.
  const nearest = Math.min(...usable.map((town) => haversineKm([lat, lng], [town.lat, town.lng])));
  return Number.isFinite(nearest) && nearest > farKm;
}

function countriesOf(candidate) {
  return [...new Set([candidate?.country, ...(candidate?.countries ?? [])].filter(Boolean).map(String))];
}

export function chooseCandidate(candidates, { near = null, area = null } = {}) {
  const all = (Array.isArray(candidates) ? candidates : []).filter(Boolean);
  if (all.length === 0) return { place: null, reason: "no_candidate", candidates: [] };

  // An entity whose OWN label is the name beats one that merely lists it as an alias.
  // This is evidence rather than a preference, and it is what separates the city of
  // Istanbul from a pub called Istanbul Grill.
  const exact = all.filter((candidate) => candidate.exact_label);
  const labelled = exact.length > 0 ? exact : all;
  // **A country the prose names refuses every candidate outside it — before the choice,
  // not only after.** The hint still cannot pick: it removes, and what is left must win on
  // the same rules as before. Without this, "Jerusalem, Israel" stayed ambiguous because a
  // town of 4,405 in New York has a population too, and Tiberias and the Dead Sea went the
  // same way (07.11.2026). Only an explicitly named country does this; a city or county in
  // the hint keeps its old, refuse-only role.
  const claimed = area ? areaNamesCountry(area, [...new Set(all.flatMap(countriesOf))]) : null;
  const inClaimed = claimed
    ? labelled.filter((candidate) => countriesOf(candidate).some((c) => c.toLowerCase() === claimed.toLowerCase()))
    : [];
  const list = inClaimed.length > 0 ? inClaimed : labelled;

  if (list.length === 1) {
    return refuseIfElsewhere({ place: list[0], reason: exact.length > 0 && all.length > 1 ? "exact_label" : "unique", candidates: all }, area, all);
  }

  if (near && finiteOrNull(near.lat) !== null && finiteOrNull(near.lng) !== null) {
    const sorted = [...list].sort((a, b) => kmApart(a, near) - kmApart(b, near));
    // The hint only speaks about its own neighbourhood. A winner hundreds of kilometres
    // away was not disambiguated by the hint, it was merely the least distant of a set
    // the hint knows nothing about.
    const winnerIsNearby = kmApart(sorted[0], near) <= HINT_RADIUS_KM;
    // And it must clearly favour one; two candidates equally close to it decide nothing.
    const clearlyFavoured = kmApart(sorted[1], near) - kmApart(sorted[0], near) > RIVAL_DISTANCE_KM;
    if (winnerIsNearby && clearlyFavoured) {
      return refuseIfElsewhere({ place: sorted[0], reason: "nearest_to_hint", candidates: all }, area, all);
    }
  }

  // Records of the same place (a settlement and its centre) cluster together; genuine
  // homonyms do not.
  const [first] = list;
  const allTogether = list.every((candidate) => kmApart(candidate, first) <= RIVAL_DISTANCE_KM);
  if (allTogether) {
    const best = [...list].sort((a, b) => (b.population ?? 0) - (a.population ?? 0))[0];
    return refuseIfElsewhere({ place: best, reason: "same_place_multiple_records", candidates: all }, area, all);
  }

  const dominant = dominantByPopulation(list);
  if (dominant) return refuseIfElsewhere({ place: dominant, reason: "dominant_population", candidates: all }, area, all);

  return { place: null, reason: "ambiguous_homonyms", candidates: all };
}

// Applied to every decision that carries a place, because the contradiction is orthogonal
// to how the candidate was chosen: Bognor was `unique`, not a tie.
function refuseIfElsewhere(decision, area, all) {
  if (!decision.place) return decision;
  // A region has no point to stand on, however confidently it was identified.
  if (isAreaNotAPoint(decision.place)) return { place: null, reason: "area_not_a_point", candidates: all };
  const known = [...new Set(all.flatMap((candidate) => [candidate.country, ...(candidate.countries ?? [])]).filter(Boolean))];
  if (!contradictsArea(decision.place, area, known)) return decision;
  return { place: null, reason: "contradicts_area", candidates: all };
}

// An entity that has no place of its own, only the one it inherited (#152).
//
// The New York Public Library resolves to Q219555 and its P625 is
// `-74.0059728, 40.7127753`. New York City's own coordinate is `-74.006111111,
// 40.712777777`. **They are the same point to about twenty metres** — the organisation
// has no location, it has the city's, copied. The film used the Fifth Avenue main branch,
// five kilometres away, and nothing on the card would have looked wrong.
//
// The issue proposed preferring P276/P159 for organisation-like entities. Measured across
// all 1,063 rows the gazetteer has placed, that is BACKWARDS:
//
//   Columbia University   own = the Morningside campus (right)   P159 = New York City, 11.2 km away
//   LACMA                 own = Wilshire Boulevard (right)       P159 = Los Angeles,   10.7 km away
//   Am. Museum of Nat.Hist own = Central Park West (right)        P159 = New York City,  8.0 km away
//
// 380 of the 1,063 are organisation-like and 61 have a P276/P159 more than a kilometre
// from where they sit. Preferring it would have moved sixty-one correct pins.
//
// So the test is the OPPOSITE comparison, and only against P159. A building's P276 is the
// street it stands on and legitimately shares its point — the British Museum is one metre
// from Great Russell Street, the Radcliffe Camera six from Radcliffe Square; fifty placed
// rows look like that and all are correct. A headquarters that close is different: it
// means the entity was never given a place, only an address in a city.
export const INHERITED_POINT_M = 100;

export function inheritsEnclosingPoint(own, headquarters) {
  const usable = (point) => finiteOrNull(point?.lat) !== null && finiteOrNull(point?.lng) !== null;
  if (!usable(own) || !usable(headquarters)) return false;
  const metresPerDegree = 111320;
  const dy = (Number(own.lat) - Number(headquarters.lat)) * metresPerDegree;
  const dx = (Number(own.lng) - Number(headquarters.lng)) * metresPerDegree
    * Math.cos((Number(own.lat) * Math.PI) / 180);
  return Math.hypot(dx, dy) <= INHERITED_POINT_M;
}

// Asked about the WINNERS only, after choosing, and never folded into
// `buildGeocodeQuery`. That query already answers 500, 502 and 504 under sustained load —
// three times in one afternoon — and a second hop to the headquarters' own coordinate is
// exactly the kind of weight that pushed the class closure to a 65-second timeout. One
// cheap lookup over a hundred ids costs a single extra query per hundred names.
export const MAX_IDS_PER_HQ_QUERY = 100;

export function buildHeadquartersQuery(wikidataIds) {
  const ids = [...new Set((Array.isArray(wikidataIds) ? wikidataIds : [])
    .filter((id) => /^Q[1-9]\d*$/.test(String(id))))].slice(0, MAX_IDS_PER_HQ_QUERY);
  if (ids.length === 0) return null;
  return `SELECT ?place ?lat ?lng ?hqLat ?hqLng WHERE {
  VALUES ?place { ${ids.map((id) => "wd:" + id).join(" ")} }
  ?place p:P625/psv:P625 ?node .
  ?node wikibase:geoLatitude ?lat ; wikibase:geoLongitude ?lng .
  ?place wdt:P159 ?hq .
  ?hq p:P625/psv:P625 ?hqNode .
  ?hqNode wikibase:geoLatitude ?hqLat ; wikibase:geoLongitude ?hqLng .
}`;
}

// Which of the asked-about entities sit on their headquarters' point.
export function inheritedPointIds(bindings) {
  const inherited = new Set();
  for (const row of Array.isArray(bindings) ? bindings : []) {
    const qid = String(row?.place?.value ?? "").split("/").pop();
    if (!/^Q[1-9]\d*$/.test(qid)) continue;
    const own = { lat: finiteOrNull(row?.lat?.value), lng: finiteOrNull(row?.lng?.value) };
    const hq = { lat: finiteOrNull(row?.hqLat?.value), lng: finiteOrNull(row?.hqLng?.value) };
    if (inheritsEnclosingPoint(own, hq)) inherited.add(qid);
  }
  return inherited;
}

// A cache row. `source` and `license` are mandatory from the first write: once CC0,
// CC BY and ODbL results are mixed in one table without them, nobody can say what
// attribution the data owes.
export function cacheRow(name, chosen) {
  if (!chosen?.place) return null;
  return {
    query_norm: normalizePlaceName(name),
    lat: chosen.place.lat,
    lng: chosen.place.lng,
    source: "wikidata",
    source_id: chosen.place.wikidata_id,
    license: WIKIDATA_LICENSE.name,
    match_reason: chosen.reason,
  };
}
